// SYNTHETIC stand-in for the 1Password CLI. Tests NEVER run the real `op`: this writes a tiny /bin/sh
// script into a fresh directory under os.tmpdir() that records its argv and environment, optionally
// writes synthetic stderr, sleeps, prints a synthetic item and exits with a chosen code. Every id, label
// and value it prints is generated by the test.
import { chmodSync, existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

export interface FakeOpBehaviour {
  /** Printed on stdout verbatim. */
  stdout?: string;
  /** Printed on stderr verbatim. */
  stderr?: string;
  /** Exit code (default 0). */
  code?: number;
  /** Seconds to sleep (via exec, so a SIGKILL ends it) before printing anything. */
  sleepSec?: number;
  /** Waits this long, then answers normally (a slow but successful read). */
  delaySec?: number;
  /** Bytes of zeros to print on stdout instead of `stdout` (output-size limit). */
  zeroBytes?: number;
  /**
   * The accounts the 1Password app on this computer has. When set, the fake answers `item get` as op 2.x does
   * instead of printing `stdout`: `--account` selects by account ID, user ID or shorthand (case-sensitive) or by
   * sign-in address (DNS, case-insensitive); none → "found no accounts for filter", several → "found multiple
   * accounts for filter"; then the vault and item are looked up by exact ID.
   */
  accounts?: FakeOpAccount[];
}

/** A SYNTHETIC 1Password account: IDs, host and items are made up by the test. */
export interface FakeOpAccount {
  /** Account ID, as `op account list` and a Private Link's `a=` show it (capitals). */
  id: string;
  userId?: string;
  shorthand?: string;
  /** Sign-in address, e.g. my.1password.com (several accounts may share one). */
  url: string;
  /** vault ID → item ID → the item JSON `op item get --format json` prints. */
  vaults: Record<string, Record<string, unknown>>;
}

// The account-aware fake's logic (run by node). It reads its argv and the model file and answers like op.
const MODEL_JS = `
const fs = require('node:fs');
const [modelFile, ...argv] = process.argv.slice(2);
const accounts = JSON.parse(fs.readFileSync(modelFile, 'utf8'));
const fail = (m) => { process.stderr.write('[ERROR] 2026/11/01 12:00:00 ' + m + '\\n'); process.exit(1); };
const flag = (n) => { const i = argv.indexOf(n); return i >= 0 ? argv[i + 1] : undefined; };
if (argv[0] !== 'item' || argv[1] !== 'get' || !argv[2]) fail('unknown command');
const filter = flag('--account');
let acct;
if (filter === undefined) {
  if (accounts.length !== 1) fail('multiple accounts signed in; select one by setting $OP_ACCOUNT or using the --account flag with the desired account UUID');
  acct = accounts[0];
} else {
  const hit = accounts.filter((a) => a.id === filter || a.userId === filter || a.shorthand === filter || a.url.toLowerCase() === filter.toLowerCase());
  if (hit.length === 0) fail('found no accounts for filter "' + filter + '"');
  if (hit.length > 1) fail('found multiple accounts for filter "' + filter + '"');
  acct = hit[0];
}
const vault = flag('--vault');
const items = vault !== undefined ? acct.vaults[vault] : undefined;
if (!items) fail('"' + vault + '" isn\\'t a vault in this account. specify the vault with its ID or name');
const item = items[argv[2]];
if (!item) fail('"' + argv[2] + '" isn\\'t an item in the "' + vault + '" vault. Specify the item with its UUID, name, or domain.');
process.stdout.write(JSON.stringify(item));
`;

export interface FakeOp {
  bin: string;
  dir: string;
  /** argv the fake was last called with, or null if it never ran. */
  argv(): string[] | null;
  /** Environment the fake saw (parsed `env` output), or null if it never ran. */
  env(): Record<string, string> | null;
  /** pid of the last run (the same process that `exec`s the sleep), or null if it never ran. */
  pid(): number | null;
  /** Replace what the next run does. */
  set(b: FakeOpBehaviour): void;
  cleanup(): void;
}

const q = (s: string) => `'${s.replace(/'/g, `'\\''`)}'`;

export function fakeOp(initial: FakeOpBehaviour = {}): FakeOp {
  const dir = mkdtempSync(join(tmpdir(), 'cbpr-fake-op-'));
  const bin = join(dir, 'op');
  const argvFile = join(dir, 'argv.txt');
  const envFile = join(dir, 'env.txt');
  const outFile = join(dir, 'stdout.txt');
  const errFile = join(dir, 'stderr.txt');
  const pidFile = join(dir, 'pid.txt');
  const modelFile = join(dir, 'accounts.json');
  const modelJs = join(dir, 'model.cjs');
  writeFileSync(modelJs, MODEL_JS);

  const set = (b: FakeOpBehaviour) => {
    writeFileSync(outFile, b.stdout ?? '');
    writeFileSync(errFile, b.stderr ?? '');
    const lines = ['#!/bin/sh', `echo $$ > ${q(pidFile)}`, `: > ${q(argvFile)}`, `for a in "$@"; do printf '%s\\0' "$a" >> ${q(argvFile)}; done`, `/usr/bin/env -0 > ${q(envFile)} 2>/dev/null || /usr/bin/env > ${q(envFile)}`, `/bin/cat ${q(errFile)} >&2`];
    if (b.sleepSec) lines.push(`exec /bin/sleep ${b.sleepSec}`);
    if (b.delaySec) lines.push(`/bin/sleep ${b.delaySec}`);
    if (b.accounts) {
      writeFileSync(modelFile, JSON.stringify(b.accounts));
      lines.push(`exec ${q(process.execPath)} ${q(modelJs)} ${q(modelFile)} "$@"`);
    } else if (b.zeroBytes) lines.push(`/usr/bin/head -c ${b.zeroBytes} /dev/zero`);
    else lines.push(`/bin/cat ${q(outFile)}`);
    lines.push(`exit ${b.code ?? 0}`);
    writeFileSync(bin, lines.join('\n') + '\n');
    chmodSync(bin, 0o700);
    rmSync(argvFile, { force: true });
    rmSync(envFile, { force: true });
    rmSync(pidFile, { force: true });
  };
  set(initial);

  return {
    bin,
    dir,
    set,
    // The shell creates the pid file before writing it: an empty or partial read is "not yet", never pid 0.
    pid: () => {
      const n = existsSync(pidFile) ? Number(readFileSync(pidFile, 'utf8').trim()) : NaN;
      return Number.isInteger(n) && n > 0 ? n : null;
    },
    argv: () => (existsSync(argvFile) ? readFileSync(argvFile, 'utf8').split('\0').slice(0, -1) : null),
    env: () => {
      if (!existsSync(envFile)) return null;
      const text = readFileSync(envFile, 'utf8');
      const entries = text.includes('\0') ? text.split('\0') : text.split('\n');
      return Object.fromEntries(entries.filter(Boolean).map((l) => [l.slice(0, l.indexOf('=')), l.slice(l.indexOf('=') + 1)]));
    },
    cleanup: () => rmSync(dir, { recursive: true, force: true }),
  };
}

/** A synthetic 26-char lowercase 1Password-style vault / item id. */
export const opId = (c: string) => c.repeat(26).slice(0, 26);
/** A synthetic 26-char 1Password-style account id (capitals, as `a=` in a Private Link). */
export const opAccountId = (c: string) => c.toUpperCase().repeat(26).slice(0, 26);
